BEGIN;
DO $$ BEGIN RAISE EXCEPTION 'DESIGN_ONLY_G0_OPEN_NOT_AUTHORIZED'; END $$;
ALTER TABLE company_private.r61_attempt_authorities ENABLE ROW LEVEL SECURITY;
ALTER TABLE company_private.r61_attempt_authorities FORCE ROW LEVEL SECURITY;
REVOKE ALL ON company_private.r61_attempt_authorities FROM PUBLIC;
GRANT SELECT,INSERT ON company_private.r61_attempt_authorities TO company_execution_functions_r58;
CREATE POLICY r61_read ON company_private.r61_attempt_authorities FOR SELECT TO company_execution_functions_r58 USING(EXISTS(SELECT 1 FROM company_private.request_contexts x WHERE x.backend_pid=pg_backend_pid() AND x.transaction_id=pg_current_xact_id() AND x.db_login=session_user AND x.writer_generation=54 AND x.tenant_id=r61_attempt_authorities.tenant_id AND x.project_id=r61_attempt_authorities.project_id));
CREATE POLICY r61_insert ON company_private.r61_attempt_authorities FOR INSERT TO company_execution_functions_r58 WITH CHECK(EXISTS(SELECT 1 FROM company_private.request_contexts x WHERE x.backend_pid=pg_backend_pid() AND x.transaction_id=pg_current_xact_id() AND x.db_login=session_user AND x.writer_generation=54 AND x.tenant_id=r61_attempt_authorities.tenant_id AND x.project_id=r61_attempt_authorities.project_id));
CREATE TRIGGER r61_immutable BEFORE UPDATE OR DELETE ON company_private.r61_attempt_authorities FOR EACH ROW EXECUTE FUNCTION company.reject_audit_mutation();
ALTER FUNCTION company_private.r61_worker_deadline(uuid,uuid) OWNER TO company_execution_functions_r58;
REVOKE ALL ON FUNCTION company_private.r61_worker_deadline(uuid,uuid) FROM PUBLIC;
ALTER FUNCTION company_private.r61_grant_deadline(uuid[],uuid,text,uuid) OWNER TO company_context_owner;
REVOKE ALL ON FUNCTION company_private.r61_grant_deadline(uuid[],uuid,text,uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION company_private.r61_grant_deadline(uuid[],uuid,text,uuid) TO company_execution_functions_r58;
GRANT SELECT ON company_private.request_contexts TO company_context_owner;
CREATE POLICY r61_context_self_read ON company_private.request_contexts FOR SELECT TO company_context_owner USING(backend_pid=pg_backend_pid() AND transaction_id=pg_current_xact_id() AND db_login=session_user AND writer_generation=54);
ALTER TABLE company_private.r61_extension_authorities ENABLE ROW LEVEL SECURITY;
ALTER TABLE company_private.r61_extension_authorities FORCE ROW LEVEL SECURITY;
REVOKE ALL ON company_private.r61_extension_authorities FROM PUBLIC;
GRANT SELECT,INSERT ON company_private.r61_extension_authorities TO company_execution_functions_r58;
CREATE POLICY r61_scope_read ON company_private.r61_extension_authorities FOR SELECT TO company_execution_functions_r58 USING(EXISTS(SELECT 1 FROM company_private.request_contexts x WHERE x.backend_pid=pg_backend_pid() AND x.transaction_id=pg_current_xact_id() AND x.db_login=session_user AND x.writer_generation=54 AND x.tenant_id=r61_extension_authorities.tenant_id AND x.project_id=r61_extension_authorities.project_id));
CREATE POLICY r61_scope_insert ON company_private.r61_extension_authorities FOR INSERT TO company_execution_functions_r58 WITH CHECK(EXISTS(SELECT 1 FROM company_private.request_contexts x WHERE x.backend_pid=pg_backend_pid() AND x.transaction_id=pg_current_xact_id() AND x.db_login=session_user AND x.writer_generation=54 AND x.tenant_id=r61_extension_authorities.tenant_id AND x.project_id=r61_extension_authorities.project_id AND x.principal_id=r61_extension_authorities.controller_id));
CREATE TRIGGER r61_immutable BEFORE UPDATE OR DELETE ON company_private.r61_extension_authorities FOR EACH ROW EXECUTE FUNCTION company.reject_audit_mutation();
ALTER FUNCTION company_private.r61_extension_deadline(uuid) OWNER TO company_execution_functions_r58;
REVOKE ALL ON FUNCTION company_private.r61_extension_deadline(uuid) FROM PUBLIC;
ROLLBACK;
